 PokerMatch m;string key,saved,folder;bool had,restored;int errors;InputSettings.BackgroundBehavior background;readonly StringBuilder log=new StringBuilder();void Check(bool ok,string label){log.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+s);File.WriteAllText(folder+"/progress.txt",log.ToString());}}
