total);Time.timeScale=1;}Restore();log.AppendLine("ERRORS="+errors+". Actual saved Unity scene/controllers/AI-policy tournaments and privacy-state observation, no physical or human devices. Native batch renders are not GPU performance evidence.");File.WriteAllText(folder+"/result.txt",log.ToString());if(!Application.isEditor)Application.Quit(errors==0?0:2);}
